def check_material_completeness(payload: dict) -> dict:
    if not isinstance(payload, dict):
        raise ValueError("Payload must be a dict")

    required_keys = {"schema_version", "materials"}
    if set(payload.keys()) != required_keys:
        raise ValueError("Invalid payload keys")

    if payload["schema_version"] != "insurance-materials-input-0.1":
        raise ValueError("Invalid schema version")

    materials = payload["materials"]
    if not isinstance(materials, list):
        raise ValueError("Materials must be a list")

    if len(materials) > 3:
        raise ValueError("Too many materials")

    IDS = ("requirement_document", "accident_scene_image", "accident_damage_image")
    MIMES = ("application/pdf", "image/png", "image/png")

    seen_ids = set()
    seen_filenames = set()

    for entry in materials:
        if not isinstance(entry, dict):
            raise ValueError("Each material must be a dict")

        entry_keys = {"material_id", "filename", "content_type"}
        if set(entry.keys()) != entry_keys:
            raise ValueError("Invalid material entry keys")

        mid = entry["material_id"]
        if not isinstance(mid, str) or mid not in IDS:
            raise ValueError("Unknown or invalid material_id")

        if mid in seen_ids:
            raise ValueError("Duplicate material_id")
        seen_ids.add(mid)

        filename = entry["filename"]
        if not isinstance(filename, str):
            raise ValueError("Filename must be a string")
        if not filename.strip():
            raise ValueError("Filename cannot be blank")
        if "/" in filename or "\\" in filename:
            raise ValueError("Filename cannot contain path separators")

        if filename in seen_filenames:
            raise ValueError("Duplicate filename")
        seen_filenames.add(filename)

        ctype = entry["content_type"]
        if not isinstance(ctype, str):
            raise ValueError("Content type must be a string")

        idx = IDS.index(mid)
        if ctype != MIMES[idx]:
            raise ValueError(f"Wrong MIME for {mid}")

    present = [mid for mid in IDS if mid in seen_ids]
    missing = [mid for mid in IDS if mid not in seen_ids]

    status = "complete" if len(present) == 3 else "incomplete"

    return {
        "schema_version": "insurance-materials-result-0.1",
        "status": status,
        "present_material_ids": present,
        "missing_material_ids": missing
    }

