import pytest
from app.insurance_poc.materials import check_material_completeness

IDS = ("requirement_document", "accident_scene_image", "accident_damage_image")
MIMES = ("application/pdf", "image/png", "image/png")

def material(index, filename=None, content_type=None):
    return {"material_id": IDS[index],
            "filename": f"material-{index}" if filename is None else filename,
            "content_type": MIMES[index] if content_type is None else content_type}

def test_complete_all():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(i) for i in range(3)]}
    res = check_material_completeness(payload)
    assert res["status"] == "complete"
    assert res["present_material_ids"] == list(IDS)
    assert res["missing_material_ids"] == []

def test_missing_one():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0), material(2)]}
    res = check_material_completeness(payload)
    assert res["status"] == "incomplete"
    assert res["present_material_ids"] == ["requirement_document", "accident_damage_image"]
    assert res["missing_material_ids"] == ["accident_scene_image"]

def test_empty_materials():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": []}
    res = check_material_completeness(payload)
    assert res["status"] == "incomplete"
    assert res["present_material_ids"] == []
    assert res["missing_material_ids"] == list(IDS)

def test_reordered_input():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(2), material(0), material(1)]}
    res = check_material_completeness(payload)
    assert res["present_material_ids"] == list(IDS)

def test_invalid_payload_type():
    with pytest.raises(ValueError):
        check_material_completeness("not a dict")

def test_invalid_schema_version():
    payload = {"schema_version": "wrong", "materials": []}
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_extra_payload_key():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [], "extra": 1}
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_missing_payload_key():
    payload = {"schema_version": "insurance-materials-input-0.1"}
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_invalid_material_entry_type():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": ["not a dict"]}
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_extra_material_key():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0, filename="test", content_type="application/pdf", extra=1)]}
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_unknown_material_id():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [{"material_id": "unknown", "filename": "f", "content_type": "a"}]}
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_duplicate_material_id():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0), material(0)]}
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_duplicate_filename():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0, filename="dup"), material(1, filename="dup")]}  
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_blank_filename():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0, filename=" ")]}
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_path_in_filename():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0, filename="dir/file")]}  
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_backslash_in_filename():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0, filename="dir\\file")]}  
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_wrong_mime():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0, content_type="image/png")]}  
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_non_string_filename():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0, filename=123)]}
    with pytest.raises(ValueError):
        check_material_completeness(payload)

def test_input_immutability():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(0), material(1), material(2)]}
    original = str(payload)
    check_material_completeness(payload)
    assert str(payload) == original

def test_too_many_materials():
    payload = {"schema_version": "insurance-materials-input-0.1", "materials": [material(i) for i in range(4)]}
    with pytest.raises(ValueError):
        check_material_completeness(payload)
